const capitalizeFirstLetter = (str) => {
  if (str === null || typeof str !== 'string' || str.length === 0) {
    return '';
  }

  const words = str.split(' ');
  const capitalizedWords = [];

  for (let i = 0; i < words.length; i += 1) {
    const word = words[i];
    if (word.length > 0) {
      const firstChar = word.charCodeAt(0);
      let capitalizedFirstChar = word.charAt(0).toUpperCase();

      if (firstChar >= 97 && firstChar <= 122) { // 'a' is 97, 'z' is 122
        capitalizedFirstChar = String.fromCharCode(firstChar - 32);
      }

      capitalizedWords.push(capitalizedFirstChar + word.slice(1));
    } else {
      capitalizedWords.push('');
    }
  }

  return capitalizedWords.join(' ');
};

