function getPrimesUpTo(limit) {
  if (limit < 2) return [];
  const sieve = new Array(limit + 1).fill(true);
  sieve[0] = false;
  sieve[1] = false;

  for (let p = 2; p * p <= limit; p += 1) {
    if (sieve[p]) {
      for (let i = p * p; i <= limit; i += p) {
        sieve[i] = false;
      }
    }
  }

  const primes = [];
  for (let i = 2; i <= limit; i += 1) {
    if (sieve[i]) {
      primes.push(i);
    }
  }
  return primes;
}

