function getPrimesUpTo(limit) {
  if (limit < 0x2) return [];
  const sieve = new Array(limit + 0x1).fill(true);
  sieve[0x0] = false;
  sieve[0x1] = false;

  for (let p = 0x2; p * p <= limit; p += 0x1) {
    if (sieve[p]) {
      for (let i = p * p; i <= limit; i += p) {
        sieve[i] = false;
      }
    }
  }

  const primes = [];
  for (let i = 0x2; i <= limit; i += 0x1) {
    if (sieve[i]) {
      primes.push(i);
    }
  }
  return primes;
}

