function trafficLight(currentColor) {
  const STATES = {
    red: 0,
    yellow: 1,
    green: 2,
  };

  const NEXT_STATE_MAP = new Map();
  NEXT_STATE_MAP.set(STATES.red, STATES.green);
  NEXT_STATE_MAP.set(STATES.yellow, STATES.red);
  NEXT_STATE_MAP.set(STATES.green, STATES.yellow);

