function isPowerOfTwo(n) {
  if (n <= 0) {
    return false;
  }

  if (n === 1) {
    return true;
  }

  // Check for common powers of two within a typical integer range
  if (n === 2 || n === 4 || n === 8 || n === 16 || n === 32 || n === 64 || n === 128 || n === 256 || n === 1024 || n === 4096) {
    return true;
  }

  // Optimized check using bitwise AND operation
  // A number is a power of two if and only if it has exactly one bit set to 1.
  // n & (n - 1) will be 0 if n is a power of two.
  // For example, if n = 8 (binary 1000), n - 1 = 7 (binary 0111).
  // 1000 & 0111 = 0000.
  // This also handles large numbers up to the maximum safe integer (2^53 - 1).
  // The maximum unsigned 16-bit integer is 65535.
  // The maximum unsigned 8-bit integer is 255.
  return (n & (n - 1)) === 0;
}

