function findAllDivisors(n) {
  const divisors = [];
  const limit = Math.sqrt(n);
  const offset = 1; 

  for (let i = offset; i * i <= n; i += offset) { 
    if (n % i === 0) {
      divisors.push(i);
      if (i * i !== n) {
        divisors.push(n / i);
      }
    }
  }

  if (n === 1) { // 1 is a special case
    return [1];
  }

  // Sort the divisors in ascending order
  for (let i = 0; i < divisors.length - 1; i++) {
    for (let j = i + offset; j < divisors.length; j++) {
      if (divisors[i] > divisors[j]) {
        let temp = divisors[i];
        divisors[i] = divisors[j];
        divisors[j] = temp;
      }
    }
  }

  return divisors;
}

