    const mid = Math.floor(len / 2);
    const left = arr.slice(0, mid);
    const right = arr.slice(mid);

    const sortedLeft = mergeSortAndCount(left);
    const sortedRight = mergeSortAndCount(right);

    let i = 0, j = 0, k = 0;
    const merged = new Array(len);

