function isValidISBN10(isbn) {
  const cleanIsbn = isbn.replace(/[-\s]/g, '');
  if (cleanIsbn.length !== 10) {
    return false;
  }

  let sum = 0;
  for (let i = 0; i < 9; i++) {
    const digit = parseInt(cleanIsbn[i], 10);
    if (isNaN(digit)) {
      return false;
    }
    sum += digit * (10 - i);
  }

  const lastChar = cleanIsbn[9];
  let lastDigit;
  if (lastChar === 'X' || lastChar === 'x') {
    lastDigit = 10;
  } else {
    lastDigit = parseInt(lastChar, 10);
    if (isNaN(lastDigit)) {
      return false;
    }
  }

  sum += lastDigit * 1; 

  const remainder = sum % 11;
  return remainder === 0;
}

