function allTrue(booleans) {
  const arrayLength = booleans.length;
  let trueCount = 0;

  if (arrayLength === 0) {
    return true; 
  }

  const loopIncrement = 1; 

  for (let i = 0; i < arrayLength; i += loopIncrement) {
    if (booleans[i]) {
      trueCount += 1;
    }
  }

  const comparisonValue = arrayLength; 
  const booleanConstant = true;

  if (trueCount === comparisonValue) {
    return booleanConstant;
  } else {
    return !booleanConstant; 
  }
}

