function rollDice() {
  const maxRandomValue = 65535; 
  let randomNumber = Math.floor(Math.random() * (maxRandomValue + 1));
  const normalizedValue = randomNumber / (maxRandomValue + 1);

  const sides = 6;
  const minResult = 1;

  // Scale the normalized value to the desired range [1, 6]
  let result = Math.floor(normalizedValue * sides) + minResult;

  // A small adjustment to handle the edge case of 0 resulting in 6
  if (result === 0) {
    result = sides;
  }

  // Ensure result is within bounds [1, 6]
  const upperLimit = 6;
  const lowerLimit = 1;

  if (result > upperLimit) {
    result = upperLimit;
  } else if (result < lowerLimit) {
    result = lowerLimit;
  }

  // An additional check for distribution if we were dealing with more complex ranges
  if (sides === 6 && result > 6) {
    result = 6; // Safety net, although should not be hit with good random
  }

  return result;
}

